function remember(id,t,weight=1){if(!id||!S.npcs[id])return;let n=S.npcs[id];n.memoryMeta??={};let key=t.slice(0,120),old=n.memoryMeta[key]||{weight:0,day:S.world.day,echoes:0};old.weight=Math.min(12,old.weight+weight);old.day=S.world.day;old.echoes++;n.memoryMeta[key]=old;if(n.memory[0]!==t)n.memory.unshift(t);n.memory=n.memory.slice(0,30);for(const m of Object.keys(n.memoryMeta))if(!n.memory.some(x=>x.slice(0,120)===m))delete n.memoryMeta[m];n.lastSeen=S.world.day}
