function detectSynergies(){let f=Object.values(S.player.fates||{}), out=[];let has=x=>f.includes(x);
 if(has("Primordial Chaosborn")&&has("Primordial Chaos"))out.push("Primordial Convergence");
 if(has("Demonkin")&&has("Heavenly Demon Physique"))out.push("Demon Sovereign Seed");
 if(has("Reincarnated Supreme Master")&&has("Heavenly Archive"))out.push("Remembered Supreme Arts");
 if(has("Limitless Evolution")&&has("Infinite Assimilation"))out.push("Endless Ascension");
 if(has("Sword Heart")&&(has("Heavenly Lightning")||has("Glacial Yin")))out.push("Heaven-Touched Sword Seed");
 if(has("Perfect Meridians")&&has("Ten Thousand Arts"))out.push("Indestructible Foundation");
 if(has("Karmic Sovereign")&&has("Reincarnated Supreme Master"))out.push("One Who Defies Fate");
 if(!out.length&&f.length===5)out.push("Balanced Destiny");S.player.synergies=out}
function fateBonus(kind){let f=S.player.fates||{},b=0;
 if(kind==="sword"&&f.Ability==="Sword Heart")b+=3;if(kind==="qi"&&f.Ability==="Perfect Meridians")b+=3;if(kind==="investigate"&&f["Unique Power"]==="Eye of Truth")b+=3;if(kind==="formation"&&f.Ability==="Divine Formation Mind")b+=4;
 if(kind==="body"&&(f.Race==="Azure Dragonkin"||f.Ability==="Heavenly Demon Physique"))b+=2;if(kind==="will"&&f.Race==="Celestial Descendant")b+=2;if(S.player.synergies.includes("Primordial Convergence"))b+=1;return b}
function xpMult(){let f=S.player.fates||{},m=1;if(f.Ability==="Ten Thousand Arts")m+=.15;if(f["Unique Power"]==="Heavenly Archive")m+=.12;if(f.Race==="Human")m+=.05;return m}
function gainAttr(k,n){let a=S.player.attrs[k];a.xp+=Math.round(n*xpMult());for(let need=70+a.v*8;a.xp>=need;need=70+a.v*8){a.xp-=need;a.v++;note(`${k} increased to ${a.v}.`)}}
