function healItem(name){
 if(!sideActionAllowed())return false;
 const supported=["Healing Salve","Qi Restoration Pill","Travel Meal","Refined Tea","Minor Healing Draught","Clear Qi Decoction","Black-Petal Antidote","Meridian Warming Tonic"];
 let item=S.player.inventory.find(x=>x.name===name&&x.qty>0);if(!item||!supported.includes(name))return false;
 const useful=name==="Healing Salve"?S.player.hp<S.player.maxHp||S.player.injuries.length>0:name==="Qi Restoration Pill"||name==="Meridian Warming Tonic"?S.player.qi<S.player.maxQi:name==="Minor Healing Draught"?S.player.hp<S.player.maxHp:name==="Black-Petal Antidote"?S.player.injuries.some(x=>/poison|venom|toxin/i.test(x.name)):name==="Refined Tea"?S.player.qi<S.player.maxQi||S.player.fatigue>0||S.player.heat>0:name==="Clear Qi Decoction"?S.player.qi<S.player.maxQi||S.player.fatigue>0:S.player.hp<S.player.maxHp||S.player.qi<S.player.maxQi||S.player.fatigue>0;if(!useful){note("You do not need this remedy right now. It remains in your belongings.");return false;}
 const before={hp:S.player.hp,qi:S.player.qi,injuries:S.player.injuries.length};item.qty--;
 if(name==="Healing Salve"){if(S.player.injuries.length)S.player.injuries.shift();S.player.hp=Math.min(S.player.maxHp,S.player.hp+30);note("Used Healing Salve.")}
 if(name==="Qi Restoration Pill"){S.player.qi=Math.min(S.player.maxQi,S.player.qi+30);note("Used Qi Restoration Pill.")}
 if(name==="Travel Meal"){S.player.hp=Math.min(S.player.maxHp,S.player.hp+12);S.player.qi=Math.min(S.player.maxQi,S.player.qi+8);changeFatigue(-8);note("Ate a Travel Meal and recovered some road-weariness.")}
 if(name==="Refined Tea"){S.player.qi=Math.min(S.player.maxQi,S.player.qi+8);S.player.heat=Math.max(0,S.player.heat-1);changeFatigue(-4);note("Drank Refined Tea.")}
 if(name==="Minor Healing Draught"){S.player.hp=Math.min(S.player.maxHp,S.player.hp+24);note("Drank a Minor Healing Draught.")}
 if(name==="Clear Qi Decoction"){S.player.qi=Math.min(S.player.maxQi,S.player.qi+24);changeFatigue(-8);note("Drank a Clear Qi Decoction.")}
 if(name==="Black-Petal Antidote"){let i=S.player.injuries.findIndex(x=>/poison|venom|toxin/i.test(x.name));if(i>=0)S.player.injuries.splice(i,1);note("Used a Black-Petal Antidote.")}
 if(name==="Meridian Warming Tonic"){S.player.qi=Math.min(S.player.maxQi,S.player.qi+18);realmGain(4);note("Used a Meridian Warming Tonic.")}
 S.actionNo++;
 const treatment=!["Travel Meal","Refined Tea"].includes(name)&&(S.player.hp>before.hp||S.player.qi>before.qi||S.player.injuries.length<before.injuries);
 if(treatment){const power=MURIM_POWERS.resolveUse(S,{eventId:S.actionNo,domain:'medicine',meaningful:true,challenge:1,success:true});if(power.ok)note(power.text);}
 save();return true;
}






