const unguardedReactiveNextScene=reactiveNextScene;reactiveNextScene=function(){return repetitionGuard(unguardedReactiveNextScene())};nextScene=reactiveNextScene;

function ui(){if(!S.created)return;refreshTitles();$("#realm").textContent=`${REALMS[S.player.realm]} • Fatigue ${S.player.fatigue||0}`;$("#clock").textContent=`Day ${S.world.day} • ${PHASES[S.world.phase]}`;$("#location").textContent=S.world.location}

function renderAppearanceCreator(){let bodySel=$("#bodyTemplate"),preview=$("#appearancePreview"),faces=$("#faceChoices"),hairs=$("#hairChoices"),palettes=$("#paletteChoices"),expressions=$("#expressionChoices");if(!bodySel||!preview||!faces||!hairs)return;let g=S.player.gender||"",a=normalizeAppearance(S.player.appearance,g,S.player.name||$("#name")?.value||"new-character");S.player.appearance=a;bodySel.value=a.body;preview.innerHTML=`<div class="atelierHalo"></div>${characterModel(a,{expression:S.player.appearance.expression,weapon:true,label:"Character appearance preview"})}<div class="atelierCaption"><b>${a.body==="female"?"Feminine":"Masculine"} • ${FACE_LABELS[a.body][a.face-1]}</b><span>${HAIR_LABELS[a.body][a.hair-1]} • ${S.player.appearance.expression.replace(/^./,x=>x.toUpperCase())}</span></div>`;faces.innerHTML=[1,2,3].map(i=>`<button type="button" aria-pressed="${a.face===i}" class="appearanceChoice visualChoice faceChoice ${a.face===i?"selected":""}" data-face="${i}"><span class="appearanceThumb">${characterModel({...a,face:i},{portrait:true,expression:"neutral",weapon:false,label:`${FACE_LABELS[a.body][i-1]} face`})}</span><b>${FACE_LABELS[a.body][i-1]}</b><small>Face ${i}</small></button>`).join("");hairs.innerHTML=[1,2,3,4,5,6].map(i=>`<button type="button" aria-pressed="${a.hair===i}" class="appearanceChoice visualChoice hairChoice ${a.hair===i?"selected":""}" data-hair="${i}"><span class="appearanceThumb">${characterModel({...a,hair:i},{portrait:true,expression:"determined",weapon:false,label:`${HAIR_LABELS[a.body][i-1]} hair`})}</span><b>${HAIR_LABELS[a.body][i-1]}</b><small>Hair ${i}</small></button>`).join("");if(palettes)palettes.innerHTML=CHARACTER_PALETTES.map((p,i)=>`<button type="button" aria-pressed="${a.palette===i}" class="paletteChoice ${a.palette===i?"selected":""}" data-palette="${i}" aria-label="Robe palette ${i+1}" style="--robe:${p.robe};--inner:${p.robe2};--trim:${p.trim};--sash:${p.sash}"><i></i><span>${i+1}</span></button>`).join("");if(expressions){let ex=MURIM_ART.expressions;expressions.innerHTML=ex.map(x=>`<button type="button" aria-pressed="${S.player.appearance.expression===x}" class="expressionChoice ${S.player.appearance.expression===x?"selected":""}" data-expression="${x}">${x.replace(/^./,c=>c.toUpperCase())}</button>`).join("")}$$('.faceChoice').forEach(b=>b.onclick=()=>{S.player.appearance.face=Number(b.dataset.face);renderAppearanceCreator();save()});$$('.hairChoice').forEach(b=>b.onclick=()=>{S.player.appearance.hair=Number(b.dataset.hair);renderAppearanceCreator();save()});$$('.paletteChoice').forEach(b=>b.onclick=()=>{S.player.appearance.palette=Number(b.dataset.palette);renderAppearanceCreator();save()});$$('.expressionChoice').forEach(b=>b.onclick=()=>{S.player.appearance.expression=b.dataset.expression;renderAppearanceCreator();save()})}
function ensureCreatorDefaults(){if(S.created)return false;const defaults={Race:"Human",Ability:"Perfect Meridians",Origin:"Nameless Village",Affinity:"Flame Yang","Unique Power":"Eye of Truth"};S.player.fates??={};let changed=false;for(const [cat,arr] of Object.entries(D.fates)){if(!arr.some(x=>x[0]===S.player.fates[cat])){S.player.fates[cat]=defaults[cat]||arr[0][0];changed=true}}return changed}
function creatorFateEffect(cat,name){const entry=D.fates[cat]?.find(x=>x[0]===name),powers=globalThis.MURIM_POWERS,power=powers?.catalog?.find(x=>x.category===cat&&x.fate===name);return power?`${power.name}: ${power.effect} Costs ${power.qi} Qi when used.`:cat==="Race"&&powers?.races?.[name]?powers.races[name]:entry?.[2]||""}
function creation(){
 const changed=ensureCreatorDefaults(),box=$("#fates"),wasOpen=!!$("#creatorPathDetails")?.open;
 if(!S.created){$("#realm").textContent="New journey";$("#clock").textContent="Choose your beginning";}
 $("#name").value=S.player.name||"";box.innerHTML="";
 const origins=document.createElement("section");origins.className="fateGroup originGroup";
 const heading=document.createElement("h2");heading.textContent="Where does your story begin?";origins.appendChild(heading);
 const intro=document.createElement("p");intro.className="creatorHint";intro.textContent="Your origin shapes the first place, people, resources, and unfinished problem you meet.";origins.appendChild(intro);
 const row=document.createElement("div");row.className="originChoices";row.setAttribute("aria-label","Choose an origin");origins.appendChild(row);
 for(const [name,,desc] of D.fates.Origin){const b=document.createElement("button");b.type="button";b.className="fate fateCard"+(S.player.fates.Origin===name?" selected":"");b.dataset.origin=name;b.setAttribute("aria-pressed",String(S.player.fates.Origin===name));b.innerHTML=`<b>${esc(name)}</b><small>${esc(desc)}</small>`;b.onclick=()=>{S.player.fates.Origin=name;for(const x of row.children){const selected=x===b;x.classList.toggle("selected",selected);x.setAttribute("aria-pressed",String(selected))}save();checkBegin()};row.appendChild(b)}
 box.appendChild(origins);
 const details=document.createElement("details");details.id="creatorPathDetails";details.className="fateDetails";details.open=wasOpen;
 const summary=document.createElement("summary");summary.textContent="Shape your path";details.appendChild(summary);
 const selected=document.createElement("p");selected.className="creatorHint creatorPathSummary";details.appendChild(selected);
 const updateSummary=()=>{selected.textContent=["Race","Ability","Affinity","Unique Power"].map(cat=>S.player.fates[cat]).join(" · ")+". These choices are optional; your starting path is ready."};updateSummary();
 const options=document.createElement("div");options.className="creatorFateOptions";details.appendChild(options);
 for(const [cat,arr] of Object.entries(D.fates)){if(cat==="Origin")continue;const field=document.createElement("div");field.className="creatorFateField";const label=document.createElement("label");label.textContent=cat;const select=document.createElement("select");select.id="creatorFate-"+cat.toLowerCase().replace(/\s+/g,"-");select.dataset.fate=cat;select.setAttribute("aria-describedby",select.id+"-effect");select.innerHTML=arr.map(([name,rarity])=>`<option value="${esc(name)}">${esc(name)} · ${esc(rarity)}</option>`).join("");select.value=S.player.fates[cat];label.appendChild(select);field.appendChild(label);const effect=document.createElement("p");effect.id=select.id+"-effect";effect.className="creatorFateEffect";effect.textContent=creatorFateEffect(cat,select.value);field.appendChild(effect);select.onchange=()=>{if(!arr.some(x=>x[0]===select.value))return;S.player.fates[cat]=select.value;effect.textContent=creatorFateEffect(cat,select.value);updateSummary();save();checkBegin()};options.appendChild(field)}
 box.appendChild(details);renderAppearanceCreator();checkBegin();if(changed)save();
}
function checkBegin(){const ready=Object.entries(D.fates).every(([cat,arr])=>arr.some(x=>x[0]===S.player.fates?.[cat]));$("#begin").disabled=!($("#name").value.trim()&&ready)}

// Each Origin now seeds a different first encounter, starting place and unresolved pressure.
// The variant is deterministic for a save, so reloads preserve the same beginning while new seeds feel different.
const ORIGIN_PROFILES={
 "Nameless Village":{pressure:"a village that survived by staying out of every ledger",startingItems:["Wild Herbs"],silver:8,sceneBias:{"jin-alley":3,"gwak-rumor":2,"cloudveil-status":1},choices:[["Ask who kept your village nameless","hanRespect","A name can be shelter—or evidence."],["Ask why the awakening recognized you","vessel","Force the room to explain the impossible."],["Watch the person hiding fear","mu","Attention is a weapon when you have no lineage."],["Study the cards before choosing an exit","formation","Survival taught you to move before the door closes."]],variants:[
  {location:"Awakening Hall",actor:"han",title:"The Name the Ledger Missed",hook:"The ceremony ledger reaches your line and stops. There is no family name, no patron mark, not even the village that raised you—only a blank space that looks recently scraped.",complication:"Han Muyeon studies the blank as if it has just become a political fact. Somewhere behind the elder gallery, someone whispers the name of a village that official maps deny exists.",aftershock:"Before the elders can decide whether a nameless person can be dangerous, a courier arrives carrying a seal from outside the sect."},
  {location:"Jade River City",actor:"jin",title:"A Stranger with Your Village's Ash",hook:"You wake beneath a rain-dark awning with ash on your sleeve and no memory of agreeing to come this far. The five cards are still warm against your palm.",complication:"Jin Seol recognizes the ash before she recognizes you. “That village was removed from three records,” she says. “Someone wanted its silence to outlive its people.”",aftershock:"A bell rings from the river district. Someone has found a second survivor—or wants you to believe they have."},
  {location:"Crane & Reed Martial Inn",actor:"baek",title:"The Person No One Can Challenge by Name",hook:"The innkeeper asks which clan will pay for your room. When you answer with the truth, the nearest table goes quiet—not from pity, but from the sudden absence of a safe assumption.",complication:"Baek Dojin laughs once and asks whether a person without a name can still make a promise. Behind him, a courier leaves a coin stamped with the mark of your village.",aftershock:"The coin is warm from another hand. Whoever left it knows you survived the awakening."}
 ]},
 "Fallen Clan":{pressure:"a ruined family name whose debts are still being collected",startingItems:["Jade Hairpin","Formation Chalk"],silver:-6,heat:1,flags:{originDebt:true},sceneBias:{"jin-alley":4,"redmoon":3,"tournament-register":2},choices:[["Ask who profited from your clan's fall","hanRespect","Make the room name the debt."],["Demand the truth about your family's records","vessel","A buried history is still a weapon."],["Confront the witness who recognizes your crest","mu","Let the enemy reveal what they know."],["Inspect the seal hidden in your inheritance","formation","Evidence survives where reputations do not."]],variants:[
  {location:"Jade River City",actor:"jin",title:"The Crest Beneath the Rain",hook:"The jade crest sewn inside your collar has not been seen in public since your clan burned. A clerk notices it, drops his brush, and pretends the ink was the problem.",complication:"Jin Seol arrives before the clerk can call anyone. She does not ask whether you are truly the last heir; she asks who taught you to hide the crest so well.",aftershock:"By nightfall, three different factions have heard that the fallen clan's bloodline has resurfaced."},
  {location:"Red Moon Ruins",actor:"jin",title:"The Ruins That Kept Your Family's Door",hook:"The sealed arch opens one finger-width when your inherited ring touches the stone. The movement is not welcome. It is recognition with a memory of anger.",complication:"Jin Seol's pendant answers with a weak pulse. A name erased from your family records appears in the dust, written by no visible hand.",aftershock:"The arch closes again, leaving a fragment of black lacquer in your palm and footsteps on the slope above."},
  {location:"Ten Thousand Lantern Market",actor:"gwak",title:"Auction of a Dead Name",hook:"A relic dealer displays your family's signet as an unclaimed curiosity. The price is low enough to be an insult and high enough to attract every watcher in the market.",complication:"Gwak Il offers to tell you who consigned it—if you admit which part of your inheritance you still want back.",aftershock:"Someone in the crowd raises a bid without showing a face. The auction has become a message meant for you."}
 ]},
 "Sect Orphan":{pressure:"a childhood shaped by sect rules, rivalries and debts no family could mediate",startingItems:["Formation Chalk","Scholar's Inkstone"],sceneBias:{"seo-test":4,"cloudveil-status":3,"seo-disciple":3},choices:[["Ask whether the sect remembers you","hanRespect","Rules are only neutral when they protect everyone."],["Ask what happened to the missing orphan records","vessel","Your past may be archived as someone else's mistake."],["Test the person who used to look away","mu","Old rivals recognize unfinished lessons."],["Read the pattern carried by your cards","formation","You learned young that walls have patterns."]],variants:[
  {location:"Cloudveil Sect",actor:"han",title:"The Child the Sect Filed Away",hook:"You know the smell of the awakening hall because you slept in its outer dormitory as a child. The elders called you a ward, never a disciple, and never explained why your file had no parent signature.",complication:"Han Muyeon sees the recognition in your face. The five cards do not merely awaken around you; they reopen a question Cloudveil buried beneath administrative language.",aftershock:"A junior disciple slips a torn page beneath your sleeve: your childhood record ends on the same day someone first wrote the word Vessel."},
  {location:"Frostblade Peak",actor:"seo",title:"The Mountain That Remembers Your Footsteps",hook:"You reach Frostblade Peak by a route no current disciple is taught. Your feet remember the turns even though your mind remembers only snow and a closed door.",complication:"Seo Hwarin waits at the final stair. She does not ask who trained you. She asks why your stance belongs to a school Cloudveil claims never existed.",aftershock:"A sword mark appears in fresh ice after you pass, matching the hand of a teacher whose name was removed from the sect rolls."},
  {location:"Awakening Hall",actor:"han",title:"The Orphan's Fifth Card",hook:"The hall is familiar in the way an old scar is familiar. You recognize which elder avoids eye contact, which bell rings late, and where a child once hid during ceremonies.",complication:"When the fifth card turns, a sealed orphan ledger opens by itself. Han Muyeon reaches for it too quickly, and that movement tells you the awakening is not new to him.",aftershock:"The ledger contains one recent addition: your name, written before you arrived."}
 ]},
 "Black Market Fighter":{pressure:"a survival reputation built where every promise had a price and witnesses were inventory",startingItems:["Healing Salve"],silver:4,heat:2,flags:{originPitFighter:true},sceneBias:{"baek-challenge":4,"gwak-rumor":3,"tournament-register":2},choices:[["Ask who bought your last fight","hanRespect","The person who paid may still own part of the story."],["Ask why the cards chose a fighter","vessel","Turn spectacle into leverage."],["Challenge the strongest person watching","mu","You learned to make hesitation expensive."],["Study your cards and nearby exits","formation","The first victory is leaving alive."]],variants:[
  {location:"Crane & Reed Martial Inn",actor:"baek",title:"Five Cards in a Fighting Den",hook:"The awakening begins with a bruise you cannot remember earning. The cards rise from the old iron ring in the inn's rear court, and every gambler suddenly remembers your face.",complication:"Baek Dojin recognizes the stance you used when you fought for food. He asks whether the cards made you special—or merely made you more expensive to kill.",aftershock:"A bookie offers odds on your next decision before you have made it."},
  {location:"Ten Thousand Lantern Market",actor:"gwak",title:"The Fighter Who Was Not Supposed to Walk Away",hook:"You come to beneath a market awning with a victory token in your teeth and six cuts that should have ended the night. The fifth card burns through the token.",complication:"Gwak Il knows the token's issuer. He also knows why the person who hired your last opponent wanted no survivor able to describe the room.",aftershock:"A masked buyer places a fresh contract on the table, addressed to the name you used before this one."},
  {location:"Jade River City",actor:"tang",title:"Blood, Qi, and a Debt That Breathes",hook:"Tang Yerin finds you standing in her clinic doorway with a fighter's reflexes and a stranger's pulse. The cards orbit your hands while she checks whether you are poisoned or merely changed.",complication:"The poison pattern matches a bout that was declared an accident. Tang asks who taught you to keep fighting after your meridians failed.",aftershock:"Someone outside the clinic calls your old ring name, then runs before you can answer."}
 ]},
 "Hidden Ancient Clan":{pressure:"old blood that carries obligations no modern faction is willing to name aloud",startingItems:["Spirit Stone","Cold Jade Talisman"],flags:{ancientSeal:true},sceneBias:{"redmoon":5,"seo-test":3,"jin-alley":3},choices:[["Ask who still remembers your clan","hanRespect","Ancient obligations become modern leverage."],["Ask why the Vessel pattern matches your blood","vessel","Force the buried history into daylight."],["Read the strongest hostile presence","mu","Power recognizes power before language does."],["Study the seal before answering anyone","formation","Old clans survive by verifying doors."]],variants:[
  {location:"Red Moon Ruins",actor:"jin",title:"Blood at the Sealed Arch",hook:"Your clan taught you never to approach a sealed ruin without a witness. The arch opens anyway, responding to blood that should have ended generations ago.",complication:"Jin Seol arrives with her pendant uncovered. The spiral on it matches the mark under your skin, and both symbols point toward a seventh channel cut out of the stone.",aftershock:"Something inside the ruin speaks in the voice of a relative you were told never existed."},
  {location:"Frostblade Peak",actor:"seo",title:"The Last House Above the Snowline",hook:"You were taught to hide your lineage beneath ordinary technique. Frostblade Peak ruins that plan when the mountain's qi bends toward you like a kneeling court.",complication:"Seo Hwarin recognizes the old form in your breathing. She does not bow, but she stops treating you as an unknown disciple.",aftershock:"A sealed letter reaches the peak before you can leave. Its wax bears your clan's extinct crest."},
  {location:"Black Heaven Palace",actor:"mu",title:"An Ancient Guest at a Black Door",hook:"The palace guards do not stop you. They step aside with the uneasy courtesy reserved for a name that should be dead but remains dangerous.",complication:"Mu Cheon greets you as if an ancestor already negotiated your entrance. He offers no explanation, only a seat beneath a portrait whose face has been scratched away.",aftershock:"The palace's inner bell rings once. A voice behind the screen says your clan's oath incorrectly."}
 ]},
 "Reincarnated Supreme Master":{pressure:"memories from another lifetime that know too much and agree on too little",startingItems:["Qi Restoration Pill","Scholar's Inkstone"],flags:{reincarnatedMemory:true},sceneBias:{"redmoon":4,"seo-test":4,"tournament-register":3},choices:[["Ask which lifetime the sect remembers","hanRespect","Authority is easier to read when you have outlived it."],["Ask why the Vessel feels familiar","vessel","A past life is evidence, not permission."],["Test the witness with a technique they should not know","mu","Let recognition become a weapon."],["Inspect the awakening formation for an old flaw","formation","You have seen this mistake before—perhaps."]],variants:[
  {location:"Black Heaven Palace",actor:"mu",title:"The Palace You Remember Wrong",hook:"You recognize the palace gate from a lifetime no one here could have witnessed. The memory says the left bell is cracked. The bell is whole.",complication:"Mu Cheon notices the moment you realize the past is not repeating cleanly. He asks which version of him you expected to meet.",aftershock:"A servant delivers a sealed manual in handwriting you remember using with a different name."},
  {location:"Awakening Hall",actor:"han",title:"The Master Beneath the Child's Skin",hook:"The five cards awaken and an old technique rises to your tongue before you remember that this body never learned it. The hall's formation is both familiar and subtly wrong.",complication:"Han Muyeon sees the technique in your breathing. He does not call it reincarnation; he calls it a security problem.",aftershock:"Your former signature appears on the back of a page written two centuries ago."},
  {location:"Cloudveil Sect",actor:"seo",title:"A Sword Saint from Another Ending",hook:"You arrive at Cloudveil with the certainty that Seo Hwarin died before she ever met you. She is alive, younger than memory, and already watching your hands.",complication:"When the cards turn, she asks why you look at her as though mourning a future she has not chosen.",aftershock:"A sword form from your former life moves through the courtyard by itself, drawn by a disciple who has never seen it."}
 ]}
};
function originProfile(){let name=S.player?.fates?.Origin,p=ORIGIN_PROFILES[name]||ORIGIN_PROFILES["Nameless Village"];return {name:name||"Nameless Village",profile:p}}
function openingRecord(){ensureNarrativeState(S);let o=originProfile(),n=S.world.narrative;if(n.openingOrigin!==o.name||!Number.isInteger(n.openingVariant)){n.openingOrigin=o.name;n.openingVariant=hash(`${S.seed}|origin-opening|${o.name}`)%o.profile.variants.length}let index=n.openingVariant%o.profile.variants.length;return {name:o.name,profile:o.profile,index,variant:o.profile.variants[index]}}
function applyOriginStart(){let o=openingRecord(),p=o.profile,v=o.variant,n=S.world.narrative;if(n.originApplied)return o;S.world.location=v.location;if(v.actor&&S.npcs[v.actor])S.npcs[v.actor].location=v.location;for(const item of p.startingItems||[])addItem(item,1);S.player.silver=Math.max(0,S.player.silver+(p.silver||0));S.player.heat=clamp(S.player.heat+(p.heat||0),0,100);for(const [k,val] of Object.entries(p.flags||{}))S.world.flags[k]=val;n.originApplied=true;n.originPressure=p.pressure;n.directorMood="watchful";S.world.readyEvents.unshift({kind:"origin",origin:o.name,variant:o.index,where:[v.location],npc:v.actor,title:`${v.title} — The First Claim`,text:v.aftershock});note(`Origin established: ${o.name}. ${p.pressure}.`);return o}
function originAftermathScene(e){let o=openingRecord(),v=o.variant,n=S.npcs[e.npc],name=n?.name||"the waiting world";return {id:`origin-aftermath-${o.name}-${o.index}`,oneShot:true,npc:e.npc,title:e.title||`${v.title} — The First Claim`,text:[e.text||v.aftershock,`${name} does not ask you to explain everything. They ask which part of your past you are willing to make visible. The answer will change what the Jianghu thinks it can demand.`,`Your origin is no longer a description on a card. It is a pressure other people can use—or a history you can rewrite.`],choices:[["Ask what they know about your origin","procTalk","Trade a controlled truth for a sharper question."],["Read the room before choosing a side","procObserve","Let other people's assumptions reveal themselves."],["Make your origin impossible to ignore","procAct","Turn history into public leverage."],["Leave before anyone can claim you","procLeave","Refuse the role they prepared for you."]]}}
function start(){if(S.created)return false;ensureCreatorDefaults();checkBegin();if($("#begin").disabled)return false;S.player.name=$("#name").value.trim();S.player.gender=S.player.appearance.body==="female"?"Female":"Male";S.player.appearance=normalizeAppearance(S.player.appearance,S.player.gender,S.player.name);S.created=true;detectSynergies();let origin=applyOriginStart();P.initialize(S.player);note(`${S.player.name} awakened five fate cards from the ${origin.name} origin at ${S.world.location}.`);$("#creation").classList.add("hidden");$("#game").classList.remove("hidden");setScene(authoredOpening());renderStory()}

function authoredOpening(){let o=openingRecord(),v=o.variant;return {id:"opening",oneShot:true,npc:v.actor,title:`${v.title} • ${o.name}`,text:[v.hook,v.complication,v.aftershock],choices:o.profile.choices}}
const authored=[
 {id:"jin-alley",oneShot:true,npc:"jin",where:["Jade River City"],title:"A Woman Who Already Knows",req:()=>S.world.day>=1,text:["Rain needles the tiled roofs of Jade River City. A woman in gray waits beneath an awning too narrow to keep her dry. She chose it for the sightlines, not comfort.","Jin Seol's gaze touches your face, your hands, then the center of your chest. A silver pendant vanishes into her sleeve.","“When the cards appeared,” she asks, “did the formation feel as if it recognized you?” She gives her name only after the question. That tells you more than the name does."],choices:[["Tell her exactly what happened","jinTruth","Trust may purchase truth."],["Ask who taught her the word ‘Vessel’","jinVessel","Turn the question back."],["Give her a deliberate false account","jinLie","Test what she already knows."],["Say nothing; study the pendant","jinPendant","Let silence do the work."]]},
 {id:"baek-challenge",oneShot:true,npc:"baek",where:["Crane & Reed Martial Inn"],title:"Iron Palm at the Reed",req:()=>S.world.day>=2,text:["A table cracks beneath Baek Dojin's palm without spilling either cup resting on it. The Crane & Reed falls quiet in stages as each patron realizes silence is safer than curiosity.","“Five cards,” he says. “People repeat those words so often they have forgotten to ask whether you can fight.” He pushes the untouched cup toward you.","“Public duel. Private spar. Or walk away.” His smile has no warmth, but neither does it carry hatred. “I will remember all three.”"],choices:[["Accept a public duel","duel","Gain fame—and witnesses."],["Offer a private spar","spar","Test skill without spectacle."],["Refuse without apology","refuse","A rivalry can survive refusal."],["Ask what he actually wants to prove","baekTalk","Challenge the motive, not the palm."]]},
 {id:"tang-clinic",oneShot:true,npc:"tang",where:["Jade River City"],title:"Blood on the Clinic Floor",req:()=>S.world.day>=2,text:["Tang Yerin is elbow-deep in someone else's blood when you enter her clinic. Three wounded escorts occupy two beds. A fourth man lies on the floor, trying not to scream.","“If you came to talk, hold this.” She presses folded cloth into your hands without looking at your face. “If you came to be important, come back after he stops dying.”","The blood smells wrong beneath the iron tang—sweet, almost floral. Poison."],choices:[["Help stabilize the wounded man","medicine","Hands first, questions later."],["Use controlled qi to slow the bleeding","qiHelp","Precision matters more than force."],["Stay clear and identify the poison","observe","Watch what others miss."]]},
 {id:"gwak-rumor",oneShot:true,npc:"gwak",where:["Ten Thousand Lantern Market"],title:"A Beggar's Expensive Silence",req:()=>S.world.day>=3,text:["Gwak Il occupies the best patch of shade in Ten Thousand Lantern Market while dressed like a man who owns nothing. His one good eye tracks three crowds at once.","“Information is like soup,” he says. “Cheap until somebody puts poison in it.” He pats the stone beside him. “You have attracted people who season generously.”"],choices:[["Buy Black Lotus information for 10 silver","buyInfo","Money is quieter than favors."],["Trade him a useful rumor","tradeRumor","Information for information."],["Ask about the missing Vessel","missing","Some questions have living owners."]]},
 {id:"seo-test",oneShot:true,npc:"seo",where:["Frostblade Peak"],title:"A Sword That Refuses Imitation",req:()=>S.world.day>=3&&S.player.skills.Swordsmanship.v>=1,text:["Frostblade Peak is quiet enough that the scrape of your boot on ice sounds like an insult. Seo Hwarin stands at the cliff edge with her sword still sheathed.","“Show me Parting Mist,” she says. When you reach for the familiar form, her gaze hardens. “No. Show me what you think it means.”","The distinction is small enough to ruin a lifetime."],choices:[["Perform the form exactly as taught","seoCopy","Safety through correctness."],["Change the final step according to your instinct","seoIntent","Risk criticism for understanding."],["Ask her to strike first so you can answer","seoAnswer","Learn through pressure."]]},

 {id:"cloudveil-status",oneShot:true,npc:"han",where:["Cloudveil Sect","Awakening Hall"],title:"A Place Beneath the Cloudveil",req:()=>S.world.day>=3&&S.player.affiliation.sect==="Unaffiliated",text:["Han Muyeon receives you in a side hall with no ceremonial chairs. That is deliberate; this is not an audience for witnesses.","“You are already being treated as though Cloudveil owns your choices,” he says. “That is dangerous if it is false, and dangerous in a different way if it becomes true.”","He sets a plain wooden disciple token on the table. “Choose a relationship with this sect before other people choose one for you.”"],choices:[["Accept status as an Outer Disciple","joinCloudveil","Gain shelter, duties, and a visible allegiance."],["Remain an honored guest","stayGuest","Keep autonomy without publicly insulting Cloudveil."],["Ask for a personal oath from Han instead of sect membership","hanOath","Make the relationship personal rather than institutional."]]},
 {id:"seo-disciple",oneShot:true,npc:"seo",where:["Frostblade Peak","Cloudveil Sect"],title:"The Sword Saint Does Not Repeat Herself",req:()=>S.world.day>=5&&S.npcs.seo.respect>=3&&!S.player.affiliation.teacher,text:["Seo Hwarin waits until you finish three repetitions before speaking. Snow gathers on her shoulders without melting.","“I can correct your hands forever,” she says. “That would only make you better at being me.” She finally turns. “If I teach you, I will teach you to become someone I cannot predict.”","There is no ceremony in the offer. That makes it heavier."],choices:[["Bow and accept Seo Hwarin as teacher","acceptSeo","A teacher changes more than technique."],["Ask for one lesson before deciding","trialSeo","Test the bond before naming it."],["Decline respectfully","declineSeo","Preserve independence and her respect."]]},
 {id:"tournament-register",oneShot:true,npc:null,where:["Jade River City"],title:"Nine Peaks Registration",req:()=>S.world.day>=4,text:["The registration court in Jade River City smells of ink, sweat, and ambition. Names are being written into ledgers that will travel farther than most contestants ever will.","A clerk pauses over your name. “Affiliation?” Behind him, two recruiters stop pretending not to listen."],choices:[["Register openly as the five-card cultivator","tourOpen","Make your reputation official."],["Register under Cloudveil's protection","tourCloud","Trade independence for shelter."],["Enter under a plain alias","tourAlias","Compete while obscuring the story."]]},
 {id:"redmoon",oneShot:true,npc:null,where:["Red Moon Ruins"],title:"The Ruins Remember",req:()=>S.world.day>=5,text:["The Red Moon Ruins should be dead stone. Instead, the sealed arch exhales when you approach. Dust rises from inscriptions no scholar has translated in two centuries.","One line changes beneath your gaze. Not opens. Not welcomes. Recognizes.","Far behind you, a pebble clicks once against another. Someone else is on the slope."],choices:[["Place your hand on the seal","seal","Accept recognition without understanding it."],["Examine the seven channels first","inspectSeal","Knowledge before contact."],["Withdraw and watch from concealment","withdraw","Let another person reveal the trap."]]}
];
function authoredLocationMatch(x){return !x.where||x.where.includes(S.world.location)}
function availableAuthored(){return authored.filter(x=>x.req()&&!S.usedScenes.includes(x.id)&&authoredLocationMatch(x))}
function storyLeads(){return authored.filter(x=>x.req()&&!S.usedScenes.includes(x.id)&&!authoredLocationMatch(x)).map(x=>({title:x.title,where:x.where?.[0]||"Unknown"})).slice(0,5)}
function relationshipChoices(id,event){
 let n=S.npcs[id],last=n.lastRelationshipApproach||'',sets=[
 [["Listen to what they need","relDeep","Build trust by discussing the concern behind the invitation."],["Offer practical help","relAssist","Commit 5 silver to their work; earn respect."],["Set a considerate boundary","relBoundary","Keep your resources and give each other space."]],
 [["Share a meal and hear their news","relMeal","Spend 3 silver on time together."],["Speak honestly about your position","relAnswer","Build personal trust without making a promise."],["Keep the exchange brief","relBoundary","Protect your time; closeness may cool."]]
 ];let index=last==='relMeal'||last==='relAnswer'?0:last==='relDeep'||last==='relAssist'?1:hash(event.title+'|'+S.world.day)%2;return sets[index].map(c=>{if(c[1]==='relAssist'&&S.player.silver<5)return ['Offer your attention instead','relAnswer','You cannot fund their work, but you can listen.'];if(c[1]==='relMeal'&&S.player.silver<3)return ['Share a quiet conversation','relAnswer','Spend time together without buying a meal.'];return c})
}
function eventScene(e){if(e.kind==="generatedQuest"&&e.questId&&S.world.generatedQuests[e.questId])return generatedQuestScene(S.world.generatedQuests[e.questId]);if(e.kind==="relationship"&&e.npc){let n=S.npcs[e.npc],warm=n.grudge<4&&(n.jealousy||0)<3;return {id:`rel-${e.npc}-${S.world.day}-${S.actionNo}`,npc:e.npc,title:e.title,text:[e.text,warm?`${n.name} chose to reach for you without needing a favor. That distinction matters in the Jianghu.`:`Old tension has matured into something that can no longer be ignored. ${n.name} remembers the exact shape of the grievance.`],choices:warm?relationshipChoices(e.npc,e):[["Hear the grievance without interrupting","relHear","Respect does not require agreement."],["Offer restitution","relRepair","Pay a real cost to repair the bond."],["Refuse to bend","relStand","Preserve pride and accept the relationship cost."]]}};return {id:`event-${e.title}-${S.world.day}-${S.actionNo}`,npc:e.npc||null,title:e.title,text:[e.text,e.kind==="fallout"?"By the time the rumor reaches you, it has acquired names, motives, and blame. Only some of them are true.":"Someone has made a move because earlier choices changed what they believe about you."],choices:[["Investigate the consequence","procObserve","Find the part of the story that is true."],["Confront whoever is responsible","procAct","Turn fallout into initiative."],["Let it develop without you","procLeave","Accept that the world can resolve its own conflicts."]]}}
const LOC={
 "Awakening Hall":{tones:["incense-heavy","too quiet","ritually ordered"],places:["bronze formation","elder gallery","paper-screen corridor"],stakes:["an elder destroying a page from the awakening record","a formation mark that was not there yesterday","a disciple repeating a forbidden phrase"]},
 "Cloudveil Sect":{tones:["pine-shadowed","bell-haunted","wind-scoured"],places:["outer training court","scripture path","disciples' dining hall"],stakes:["a senior disciple quietly testing your reputation","an elder hiding disagreement behind etiquette","a sealed letter arriving under the wrong name"]},
 "Jade River City":{tones:["rain-polished","lantern-lit","crowded"],places:["river quay","tea street","narrow book market"],stakes:["a tail trying too hard to look ordinary","a merchant recognizing you from a rumor","two factions meeting where neither should be"]},
 "Ten Thousand Lantern Market":{tones:["perfumed","noisy","gold-lit"],places:["medicine arcade","relic lane","covered auction steps"],stakes:["a counterfeit relic reacting to your qi","a whispered auction invitation","a thief choosing the wrong pocket"]},
 "Crane & Reed Martial Inn":{tones:["smoke-warmed","crowded","watchful"],places:["common room","rear courtyard","second-floor gallery"],stakes:["a challenge disguised as a toast","a courier with blood on one cuff","a conversation that stops when you enter"]},
 "Frostblade Peak":{tones:["snow-bright","knife-cold","silent"],places:["sword terrace","frozen stair","cliff shrine"],stakes:["a sword mark no disciple can explain","Seo Hwarin waiting without announcing why","a training scar appearing in fresh ice"]},
 "Red Moon Ruins":{tones:["ash-gray","unnaturally still","red-lit"],places:["collapsed vestibule","burial corridor","sealed lower stair"],stakes:["an inscription changing after you pass","footprints ending at a wall","a pulse of qi matching your heartbeat"]},
 "Hundred Herb Valley":{tones:["herb-sweet","mist-soft","deceptively peaceful"],places:["terraced dispensary","stone drying court","bamboo infirmary"],stakes:["a physician refusing a politically powerful patient","a stolen formula surfacing under another name","a patient carrying poison no one admits recognizing"]},
 "Black Heaven Palace":{tones:["black-lacquered","ceremonially quiet","oppressively elegant"],places:["guest court","obsidian bridge","inner audience corridor"],stakes:["an invitation that sounds too much like an order","two enforcers debating whether you count as a guest","a sealed command mentioning your name"]}
};
function activeThread(){return Object.entries(S.world.quests).sort((a,b)=>b[1].stage-a[1].stage)[0]?.[0]||"Vessel Mystery"}
function proceduralThreadContext(){
 const narrative=S.world.narrative;
 if(!narrative.threadRecaps||typeof narrative.threadRecaps!=="object"||Array.isArray(narrative.threadRecaps))narrative.threadRecaps={};
 const entries=Object.entries(S.world.quests).filter(([,q])=>q.status==="Active"&&q.stage>0&&typeof q.summary==="string"&&q.summary.trim()).sort((a,b)=>b[1].stage-a[1].stage);
 for(const [name,q] of entries){
  const signature=JSON.stringify([q.stage,q.summary]);
  if(narrative.threadRecaps[name]===signature)continue;
  narrative.threadRecaps[name]=signature;
  return q.summary.trim();
 }
 return "";
}
function proceduralScene(){
 let r=rng(hash(`${S.seed}|scene|${S.actionNo}|${S.world.day}|${S.world.phase}|${S.world.location}`)),loc=LOC[S.world.location]||LOC["Jade River City"],actors=[null,...Object.keys(S.npcs).filter(k=>S.npcs[k].location===S.world.location)],thread=activeThread(),candidates=[];
 for(const stake of loc.stakes)for(const place of loc.places)for(const tone of loc.tones)for(const id of actors){let fp=`${S.world.location}|${stake}|${place}|${tone}|${id||"none"}|${thread}`;if(!S.recentBeats.includes(fp)&&!S.world.narrative.recentSignatures.includes(fp))candidates.push({stake,place,tone,id,fp})}
 if(!candidates.length){S.recentBeats=[];for(const stake of loc.stakes)for(const place of loc.places)for(const tone of loc.tones)candidates.push({stake,place,tone,id:null,fp:`${S.world.location}|${stake}|${place}|${tone}|none|${thread}`})}
 let c=pick(candidates,r);S.recentBeats.unshift(c.fp);S.recentBeats=S.recentBeats.slice(0,30);S.world.narrative.recentSignatures.unshift(c.fp);S.world.narrative.recentSignatures=S.world.narrative.recentSignatures.slice(0,60);
 let n=c.id?S.npcs[c.id]:null,L=S.world.locations[S.world.location],hist=L?.history?.[0],faction=Object.entries(S.world.factions).sort((a,b)=>b[1].awareness-a[1].awareness)[0],memory=n?salientMemory(n):null,phase=PHASES[S.world.phase];
 let openings=[`The ${c.place} is ${c.tone} when you arrive.`,`By ${phase.toLowerCase()}, the ${c.place} has taken on a ${c.tone} stillness.`,`You notice the change in the ${c.place} before anyone speaks: the air is ${c.tone}.`,`At the ${c.place}, routine has broken in one small place. Everything around it feels ${c.tone}.`];
 let actorLine=n?[`${n.name} is already there. Their first look is not neutral.`,`You recognize ${n.name} before they acknowledge you. The delay is deliberate.`,`${n.name} notices you at almost the same instant you notice them; neither of you gets the advantage of pretending otherwise.`][Math.floor(r()*3)]:[`The people nearby carry on with their own business until the disturbance draws their attention.`,`A few heads turn, then return to the matter at hand.`,`You have a moment to watch before anyone asks you to take a side.`][Math.floor(r()*3)];
 let memoryLine=memory?`${n.name} has not forgotten: ${memory}`:hist&&/[.!?…]$/.test(hist.trim())?`An earlier incident still matters here: ${hist}`:"";
 let tension=[`The immediate problem sharpens: ${c.stake}.`,`Then the detail everyone has been avoiding becomes impossible to ignore: ${c.stake}.`,`What first looked incidental resolves into the actual problem: ${c.stake}.`][Math.floor(r()*3)];
 let larger=proceduralThreadContext();
 let text=[pick(openings,r),actorLine,[memoryLine,tension].filter(Boolean).join(" "),larger].filter(Boolean);
 let choices=n?[[`Address ${n.name} directly`,"procTalk","Relationship history changes the answer."],["Observe before committing","procObserve","Read the room and the hidden incentives."],["Act before anyone else can","procAct","Seize initiative; accept exposure."],["Leave the matter unresolved","procLeave","The world will continue without you."]]:[["Investigate quietly","procObserve","Gather evidence without declaring a side."],["Intervene openly","procAct","Change the situation and become part of the story."],["Follow the most suspicious person","procFollow","Trade safety for information."],["Walk away","procLeave","Absence is still a choice."]];
 if((S.player.skills.Investigation?.v||0)>=5)choices.splice(1,0,["Reconstruct what happened","procReconstruct",`Use ${S.player.skills.Investigation.specialty||"trained investigation"} to connect evidence across scenes.`]);
 if((S.player.skills.Persuasion?.v||0)>=5&&n)choices.splice(1,0,["Name the tension nobody is saying aloud","procReadPerson",`Use ${S.player.skills.Persuasion.specialty||"social experience"} and your history with them.`]);
 if(S.player.qi>=3)choices.splice(-1,0,["Read the qi pattern beneath the incident","procQiRead","Spend 3 Qi to notice what mundane evidence misses."]);
 if(S.player.fates["Unique Power"]==="Eye of Truth")choices[3]=["Use the Eye of Truth","fateEye","See what ordinary observation misses."];else if(S.player.fates["Unique Power"]==="Karmic Sovereign"&&n)choices[3]=["Read the karmic thread between you","fateKarma","Learn the emotional debt beneath the words."];
 let title=pick([c.stake[0].toUpperCase()+c.stake.slice(1),`${c.place[0].toUpperCase()+c.place.slice(1)} — ${phase}`,`Whispers at the ${c.place}`,`${phase} at the ${c.place}`],r);
 return {id:`proc-${S.world.day}-${S.world.phase}-${++S.world.eventSerial}`,procedural:true,npc:c.id,title,text,choices}
}
function nextScene(){S.world.deferredScenes=S.world.deferredScenes.filter(x=>!x.questId||S.world.generatedQuests[x.questId]?.status==="Active");let di=S.world.deferredScenes.findIndex(queueSceneAvailable);if(di>=0)return S.world.deferredScenes.splice(di,1)[0];S.world.readyEvents=S.world.readyEvents.filter(x=>!x.questId||S.world.generatedQuests[x.questId]?.status==="Active");let ei=S.world.readyEvents.findIndex(queueSceneAvailable);if(ei>=0)return eventScene(S.world.readyEvents.splice(ei,1)[0]);let a=availableAuthored();if(a.length){let x=a[0];S.usedScenes.push(x.id);return x}let q=Object.values(S.world.generatedQuests).find(q=>q.status==="Active"&&q.location===S.world.location&&q.lastScene!==S.world.day);if(q){q.lastScene=S.world.day;return generatedQuestScene(q)}return proceduralScene()}
function setScene(x){
 scrollToStory();
 if(!x||!Array.isArray(x.choices)||!x.choices.length)throw new Error('Cannot enter a scene without choices');
 let n=S.world.narrative;n.recentContent??=[];
 n.recentContent.unshift({relationship:x.id?.startsWith("rel-")||false,id:x.id,family:(x.title||'untitled').split(' • ')[0],npc:x.npc||null,structure:x.choices.map(c=>c[1]).join('|'),day:S.world.day});n.recentContent=n.recentContent.slice(0,24);
 if(x.procedural){const unique=[...new Map(x.choices.map(c=>[c[1],c])).values()];const insight=unique.find(c=>['fateEye','fateKarma','procQiRead','procReconstruct','procObserve'].includes(c[1]));const active=unique.find(c=>c[1]===(x.npc&&S.actionNo%2?'procTalk':'procAct'))||unique.find(c=>c!==insight&&c[1]!=='procLeave');const leave=unique.find(c=>c[1]==='procLeave');x={...x,choices:[insight,active,leave].filter(Boolean)}}S.scene=x;if(x.oneShot&&!S.usedScenes.includes(x.id))S.usedScenes.push(x.id);rememberNarrative(x);S.reaction=null;S.flow={mode:"scene",prosePage:0,choicePage:0,resolvedSceneId:null};save()}

const effects={
 jinTruth:["Jin Seol listens without interruption. At the mention of the fifth card, her thumb presses white against the pendant hidden in her sleeve. “That matches the seventh record,” she whispers, then realizes you heard. The rain suddenly seems louder.",s=>{s.npcs.jin.trust+=4;believe("jin","honest",3);remember("jin","Player gave her a complete account of the five-card awakening.");s.world.threads["Vessel Mystery"]+=2;gainSkill("Investigation",8)}],
 jinVessel:["For the first time, Jin Seol looks caught rather than cautious. “My brother,” she says after a silence too long to be calculated. “Vessel Seven.” Her jaw tightens. “Most of them died. One did not. And someone erased the survivor's name.”",s=>{s.npcs.jin.trust+=2;s.npcs.jin.known.push("Vessel Seven was Jin Seol's brother");s.world.flags.vesselSeven=true;gainAttr("Perception",8)}],
 jinLie:["She lets you finish the lie. “Interesting.” Nothing in her voice says she believes it. When she leaves, she chooses a route that lets her watch your reflection in six shop windows. You have learned something: she already possessed enough of the truth to recognize its absence.",s=>{s.npcs.jin.trust-=3;s.npcs.jin.respect++;believe("jin","honest",-4);gainSkill("Deception",9)}],
 jinPendant:["You do not answer. Your eyes drop once, deliberately, toward her sleeve. Jin Seol freezes. “You saw it.” Not a question. She removes the pendant: its etched spiral matches the faint mark left by your awakening formation.",s=>{s.npcs.jin.respect+=3;s.world.flags.pendantMatch=true;gainAttr("Perception",12)}],
 duel:["Baek's Iron Palm rolls his sleeve once. “Good.” The inn's spectators retreat from the center without being asked. What happens next will be a real fight, not a paragraph pretending to be one.",s=>{s.player.heat+=2;s.npcs.baek.respect+=2;s.world.flags.pendingCombat={enemy:"Baek Dojin",difficulty:15,npc:"baek"}}],
 spar:["Behind the inn, Baek stops performing for the crowd. His stance changes with it. “Now we can learn something.” The first exchange is faster and kinder than a duel, but not by much.",s=>{s.npcs.baek.trust+=2;s.npcs.baek.respect+=3;gainSkill("Unarmed",11);gainAttr("Perception",7);realmGain(3)}],
 refuse:["Baek waits for an excuse. You give him none. “Fine,” he says eventually. “Then I will wait until you want something from me.” The rivalry does not end. It becomes patient.",s=>{s.npcs.baek.respect++;remember("baek","Player refused his first challenge without apologizing.");schedule("baekReturn",2)}],
 baekTalk:["His brows draw together. No one has asked him that today. “That the stories are about a person,” he says, “not an omen.” He looks at his own palm. “And maybe that mine can become one too.” The challenge suddenly feels less simple.",s=>{s.npcs.baek.trust+=2;s.npcs.baek.respect+=2;gainSkill("Persuasion",8)}],
 medicine:["Tang's instructions arrive faster than courtesy permits. You obey. Twenty brutal minutes later, the wounded man's breathing evens. Only then does she ask your name. When she hears it, her hands pause for exactly one heartbeat.",s=>{s.npcs.tang.trust+=4;s.npcs.tang.debt++;believe("tang","merciful",3);gainSkill("Medicine",16);gainAttr("Will",6)}],
 qiHelp:["You thread qi beside ruptured vessels without trying to heal what you do not understand. Tang notices the restraint. “Good. Most cultivators use more power when they need more precision.” It is the first compliment she gives you.",s=>{s.npcs.tang.respect+=4;gainSkill("Qi Control",15+fateBonus("qi"));gainAttr("Spirit",8);realmGain(3)}],
 observe:["You keep your hands away and your attention sharp. Beneath the smell of blood is a floral sweetness. Tang follows your gaze to the blackening under the patient's nails. “That,” she says softly, “was not there when they left the escort road.”",s=>{gainAttr("Perception",12);gainSkill("Medicine",7);s.world.flags.blackLotusPoison=true}],
 buyInfo:["Gwak counts your coins before he talks. “The respectable accounting office beside the river pays men who never file taxes.” He refuses to repeat the sentence.",s=>{if(s.player.silver<10){s.world.flags.purchaseFailed=true;return}s.player.silver-=10;s.world.flags.accountingOffice=true;s.world.threads["Black Lotus Trail"]+=2;s.npcs.gwak.trust++}],
 tradeRumor:["You offer something true enough to be useful and incomplete enough to be safe. Gwak's grin says he appreciates the craftsmanship. “Now you're learning how cities breathe.”",s=>{s.npcs.gwak.respect+=3;gainSkill("Deception",10);s.player.heat=Math.max(0,s.player.heat-Math.floor(s.player.skills.Deception.v/3));s.world.rumors.unshift("Someone is buying sealed Red Moon fragments through intermediaries.")}],
 missing:["Gwak stops smiling. “There are questions that cost money and questions that cost friends.” His good eye narrows. “That one costs both.” After a pause, he scratches a seven into the dust and wipes it away.",s=>{s.npcs.gwak.trust++;s.world.threads["Vessel Mystery"]++;remember("gwak","Player is actively searching for the missing Vessel.")}],
 seoCopy:["Seo Hwarin watches the form without blinking. When you finish, she says, “Correct.” The word feels like a punishment. “If correctness were enough, manuals would be swordsmen.”",s=>{gainSkill("Swordsmanship",8);gainArt("Cloudveil Sword Foundation",7,"Parting Mist");s.npcs.seo.respect-=1}],
 seoIntent:["You change the last step. It is uglier than the manual and truer to the opening you saw. Seo's sword leaves its sheath one finger-width, then stops. “Again,” she says. That is the closest thing to praise on the mountain.",s=>{gainSkill("Swordsmanship",13+fateBonus("sword"));gainArt("Cloudveil Sword Foundation",18,"Parting Mist");s.npcs.seo.respect+=4;s.npcs.seo.trust++}],
 seoAnswer:["“Then watch.” Seo's blade appears where your throat would have been if you had obeyed your eyes. Your body answers late—but your second answer is better. She repeats the strike until fear becomes information.",s=>{gainAttr("Perception",11);gainSkill("Swordsmanship",12);gainArt("Cloudveil Sword Foundation",14,"Parting Mist");s.npcs.seo.respect+=3}],

 joinCloudveil:["Han turns the wooden token over and writes your name on the unfinished side himself. “Outer Disciple is a low rank,” he says. “That is a gift. It gives you room to become dangerous before bureaucracy notices.”",s=>{s.player.affiliation={sect:"Cloudveil Sect",rank:"Outer Disciple",teacher:s.player.affiliation.teacher,contribution:0};s.world.factions["Orthodox Alliance"].awareness+=2;s.player.rep+=1;remember("han","Player voluntarily became a Cloudveil Outer Disciple.")}],
 stayGuest:["Han retrieves the token without offense. “Then guest you remain. I will defend that distinction when others find it inconvenient.” The absence of a sect rank becomes its own kind of declared position.",s=>{s.player.affiliation.rank="Honored Guest";s.npcs.han.trust+=2;remember("han","Player chose honored-guest status over formal Cloudveil membership.")}],
 hanOath:["Han studies you for a long moment, then sets the sect token aside. “You understand institutions too quickly.” He offers his right hand. “My protection, while your conduct does not make me regret it. Your honesty, when the truth threatens my sect.”",s=>{s.player.affiliation.rank="Sect Master's Guest";s.npcs.han.trust+=4;s.npcs.han.debt+=1;believe("han","honest",2)}],
 acceptSeo:["Seo Hwarin accepts the bow by drawing her sword. The first lesson begins before your head rises. “A disciple of mine does not inherit answers,” she says as cold steel stops beside your ear. “Only better questions.”",s=>{s.player.affiliation.teacher="Seo Hwarin";s.player.arts["Frostblade Intent"]={mastery:1,rank:"Initiate",tech:["Stillness Before Snow"],proficiency:{},mutations:{},insights:[],lineage:"Frostblade Peak",inherited:{"Stillness Before Snow":{from:"Seo Hwarin",day:s.world.day}}};s.player.lineages??={};s.player.lineages.frostblade={lessons:1,insight:30,standing:6,lastLessonDay:s.world.day};s.npcs.seo.trust+=4;s.npcs.seo.respect+=3;note("Teacher gained: Seo Hwarin. Frostblade lineage opened.")}],
 trialSeo:["“Good,” Seo says, as if refusal would have disappointed her. She teaches you one breathing interval between decision and motion. It feels useless until you realize your sword hand has stopped tensing before every attack.",s=>{gainSkill("Swordsmanship",15);gainAttr("Will",8);s.npcs.seo.respect+=2}],
 declineSeo:["Seo's eyes narrow, then soften by a degree most people would miss. “Then become strong enough that I regret asking.” She does not withdraw the possibility. She simply refuses to cheapen it by repeating herself.",s=>{s.npcs.seo.respect+=2;remember("seo","Player declined formal discipleship without insulting the offer.")}],
 tourOpen:["The clerk writes your real name, then adds a second notation in red. By the time you leave the court, three recruiters know which bracket you entered.",s=>{s.world.flags.tournamentEntered=true;s.world.threads["Nine Peaks Tournament"]+=2;gainRep(5,"tournament registration");s.player.heat+=3}],
 tourCloud:["Cloudveil's seal lands beside your name. It buys protection and creates a debt everyone can see. An Orthodox observer makes a note without looking at you.",s=>{s.world.flags.tournamentEntered=true;s.world.threads["Nine Peaks Tournament"]+=2;s.world.factions["Orthodox Alliance"].awareness+=4;gainRep(2,"tournament registration")}],
 tourAlias:["You offer a plain name and an ordinary affiliation. The clerk accepts it. The man behind you does not; his eyes linger on your hands as if he recognizes the way you carry a sword.",s=>{s.world.flags.tournamentEntered=true;s.world.flags.tournamentAlias=true;s.world.threads["Nine Peaks Tournament"]++;gainSkill("Deception",10)}],
 seal:["The stone is cold for one heartbeat. Then every meridian in your arm answers. Deep beneath the ruins, something enormous completes the first half of a breath. Your five fate cards flare inside your dantian without being summoned.",s=>{s.world.flags.redMoonRecognized=true;s.player.heat+=3;realmGain(12);gainAttr("Spirit",15);if(!s.player.inventory.some(x=>x.name==="Red Moon Seal Fragment"))s.player.inventory.push({name:"Red Moon Seal Fragment",qty:1,type:"Quest"})}],
 inspectSeal:["Seven channels feed the seal. Six terminate in burial marks. The seventh has been scraped away with a tool narrow enough to fit between the old characters. Whoever erased it understood the formation.",s=>{gainSkill("Formations",18+fateBonus("formation"));gainAttr("Insight",14);s.world.flags.seventhSeal=true;s.world.threads["Vessel Mystery"]+=2}],
 withdraw:["You leave the arch untouched and vanish into broken pines above the slope. An hour later, a masked figure approaches the exact stone you marked. The seal opens for them too—but not willingly. Their scream carries halfway up the ridge.",s=>{gainAttr("Will",8);schedule("ruinIntruder",1);s.world.rumors.unshift("A masked cultivator was wounded inside Red Moon Ruins.")}],
 relAssist:["You put five silver toward their work and agree on what it will cover. The help is concrete, and they remember that you took their concerns seriously.",s=>{let id=S.scene.npc,n=s.npcs[id];if(s.player.silver<5)return;s.player.silver-=5;n.respect+=3;n.debt+=1;n.lastRelationshipApproach='relAssist';refreshRelation(id);remember(id,'Contributed five silver to my work.',2);gainLifeSkill('Commerce',4)}],
 relBoundary:["You explain what you can offer and where you need room. They accept the answer, though the conversation ends sooner than they hoped.",s=>{let id=S.scene.npc,n=s.npcs[id];n.bond=Math.max(0,n.bond-1);n.respect+=1;n.lastRelationshipApproach='relBoundary';refreshRelation(id);remember(id,'Asked for space without insulting me.');gainAttr('Will',3)}],
 relAnswer:["You answer without hiding behind sect etiquette or useful ambiguity. The conversation wanders into small things—food, weather, an old embarrassment—and becomes more intimate because no one is extracting information.",s=>{let id=S.scene.npc,n=s.npcs[id];n.lastRelationshipApproach="relAnswer";n.bond+=3;n.trust+=2;n.affection+=1;refreshRelation(id);remember(id,"Player answered a private message with genuine personal attention.");gainLifeSkill("Etiquette",5)}],
 relMeal:["You choose a table instead of a strategy room. Shared dishes create pauses where neither of you has to perform. By the end, one private joke exists that did not exist before.",s=>{let id=S.scene.npc,n=s.npcs[id];if(s.player.silver<3)return;s.player.silver-=3;n.lastRelationshipApproach="relMeal";n.bond+=4;n.affection+=2;refreshRelation(id);remember(id,"Shared an unhurried meal with the player.");gainLifeSkill("Cooking",4)}],
 relDeep:["You ask the question beneath the message. Silence follows, then an answer with edges left deliberately unpolished. Whatever else happens, this is now something you know because you were trusted with it.",s=>{let id=S.scene.npc,n=s.npcs[id];n.lastRelationshipApproach="relDeep";n.bond+=3;n.trust+=3;refreshRelation(id);remember(id,"Trusted the player with a deeper personal concern.");gainSkill("Persuasion",7)}],
 relHear:["You let the grievance finish before defending yourself. Being heard does not erase what happened, but anger loses some of its need to repeat itself.",s=>{let id=S.scene.npc,n=s.npcs[id];n.grudge=Math.max(0,n.grudge-2);n.jealousy=Math.max(0,(n.jealousy||0)-1);n.respect+=2;n.bond+=1;refreshRelation(id);gainLifeSkill("Etiquette",6)}],
 relRepair:["You make restitution in a form that costs enough to be credible. The relationship is not reset; it changes direction.",s=>{let id=S.scene.npc,n=s.npcs[id],cost=Math.min(15,s.player.silver);s.player.silver-=cost;n.grudge=Math.max(0,n.grudge-4);n.jealousy=Math.max(0,(n.jealousy||0)-4);n.trust+=2;n.bond+=2;refreshRelation(id)}],
 relStand:["You refuse to apologize for a choice you still believe was right. The answer is clean, and so is the distance it creates.",s=>{let id=S.scene.npc,n=s.npcs[id];n.grudge+=1;n.jealousy=(n.jealousy||0)+1;n.respect+=1;n.bond=Math.max(0,n.bond-2);refreshRelation(id);gainAttr("Will",5)}],
 fateEye:["The Eye of Truth opens without light. Posture becomes circulation. Lies become hesitation. You see a hidden qi knot where an ordinary observer would see only calm—and the knot points toward the person actually controlling the exchange.",s=>{gainSkill("Investigation",12);gainAttr("Perception",8);s.world.flags.truthSeen=(s.world.flags.truthSeen||0)+1}],
 fateKarma:["For a breath, the social world becomes visible as weight. Gratitude pulls warm. Fear tightens like wire. Between you and the person before you runs a thread carrying more obligation than either of you has admitted aloud.",s=>{gainAttr("Insight",10);if(S.scene?.npc)S.npcs[S.scene.npc].trust+=1}]
};
function procEffect(a,label,npc){let n0=npc?S.npcs[npc]:null;if(a==="procReconstruct")return [`You stop treating the scene as a single incident. Footprints, phrasing, timing, and the last rumor you dismissed begin to align. What looked accidental now has a sequence—and sequences imply intent.`,()=>{gainSkill("Investigation",11);gainAttr("Insight",6);S.world.threads["Vessel Mystery"]+=1;if(npc)remember(npc,"Player reconstructed a hidden sequence instead of accepting the obvious story.",2)}];if(a==="procReadPerson")return [n0?`You name the tension without accusing ${n0.name}. For one heartbeat their practiced response arrives too late. The hesitation tells you which part of the subject is personal.`:`You name the social pressure in the room and watch who reacts first.`,()=>{gainSkill("Persuasion",10);if(npc){n0.trust+=1;n0.bond+=1;remember(npc,"Player noticed what I was feeling before I said it.",3)}}];if(a==="procQiRead")return [`You let ordinary detail blur and attend to circulation instead. Residual qi clings to one object in the scene with a rhythm that does not belong to the current witnesses.`,()=>{S.player.qi=Math.max(0,S.player.qi-3);gainSkill("Qi Control",7);gainAttr("Spirit",5);S.world.flags.qiEvidence=(S.world.flags.qiEvidence||0)+1}];let n=npc?S.npcs[npc]:null;if(a==="procTalk")return [n?`${n.name} does not answer immediately. Their ${NPC_VOICE[npc]?.cadence||"careful"} way of speaking is more revealing than the words. “You want the version I tell strangers, or the one your earlier choices earned?” The answer that follows is narrower than a confession and more useful than a rumor.`:"A witness answers only after checking who else can hear.",()=>{gainSkill("Persuasion",9+skillSpecialtyBonus("Persuasion"));if(npc){n.trust+=2;remember(npc,`Player chose direct conversation during ${S.scene.title}.`)}}];if(a==="procObserve")return [`You delay action long enough for the scene to develop edges: who avoids eye contact, which exit remains clear, whose story depends on everyone moving quickly. The mystery gets smaller. The danger gets more specific.`,()=>{gainAttr("Perception",8+fateBonus("investigate"));gainSkill("Investigation",10+skillSpecialtyBonus("Investigation"))}];if(a==="procAct")return [`You move before the room agrees on a safer version of events. For several breaths, everyone else is reacting to you. It works—but by tonight, people who were not present will know that you were.`,()=>{gainAttr("Agility",7);gainRep(2,"public action");S.player.heat+=1;realmGain(3);if(npc)n.respect+=2}];if(a==="procFollow")return [`You let the obvious problem pass and follow the person trying hardest to escape it. Two alleys, a dye shop, and a courtyard later, you do not have a name. You have a route—and routes can be followed twice.`,()=>{gainSkill("Stealth",11);gainSkill("Investigation",7);S.player.heat=Math.max(0,S.player.heat-Math.floor(S.player.skills.Stealth.v/4));S.world.flags.hiddenRoute=true}];if(a==="procLeave")return [`You leave. Nothing freezes behind you. Voices resume, bargains conclude, and someone else makes the decision you declined. The world does not punish absence; it simply uses it.`,()=>{scheduleFallout(1,{location:S.world.location,text:`The unresolved incident at ${S.world.location} was settled after ${S.player.name} departed.`});gainAttr("Will",3)}];return null}
function customEffect(t,npc){let q=t.toLowerCase(),n=npc?S.npcs[npc]:null,mem=n?.memory?.[0];if(/attack|strike|fight|draw|kill|punch|slash|duel/.test(q))return [n?`${n.name}'s posture changes before their expression does. The next exchange will be fought rather than narrated.`:"Your intent becomes unmistakable. Someone accepts the challenge.",()=>{S.player.heat+=2;S.world.flags.pendingCombat={enemy:n?.name||"Jianghu Challenger",difficulty:n?14:11,npc}}];if(/ask|say|tell|speak|question|why|who|what|how|explain|promise/.test(q)){let trust=n?.trust||0,voice=NPC_VOICE[npc];return [n?`${n.name} listens all the way through. ${mem?`They are still carrying the memory of this: ${mem} `:""}${trust>=4?"They answer with less armor than before.":trust<0?"Their answer is technically responsive and emotionally closed.":"They choose each word before giving it to you."} ${voice?`For ${n.name}, ${voice.truth} matters more than comfort.`:""}`:`You put the question into the room. One witness looks away too quickly; another repeats a phrase you heard earlier. The reactions are more useful than the first answer.`,()=>{gainSkill("Persuasion",7);gainSkill("Investigation",4);if(npc){n.trust+=q.includes("please")?2:1;believe(npc,"honest",q.includes("promise")?1:0);remember(npc,`Player said: “${t}”`)}}]}
 if(/train|practice|meditat|cultivat|circulate/.test(q))return ["You settle your breathing. Rest can restore your condition; your skills grow through real challenges, useful work and resolved encounters.",()=>{}];if(/heal|salve|pill|medicine/.test(q))return [`You stop treating recovery as an interruption and make it part of cultivation. Pain becomes information once you stop arguing with it.`,()=>{if(S.player.injuries.length&&S.player.inventory.some(x=>x.name==="Healing Salve"&&x.qty))healItem("Healing Salve");else gainSkill("Medicine",5)}];if(/leave|walk|go to|travel|head to/.test(q)){let target=D.locations.find(x=>q.includes(x.toLowerCase()));return [`You leave before the scene can decide what role you were supposed to play. ${target?`You prepare for the road toward ${target}.`:"The unresolved matter continues without you."}`,()=>{if(target)S.world.flags.pendingTravel=target;else scheduleFallout(1,{location:S.world.location});gainSkill("Survival",4)}]}if(/steal|sneak|hide|follow|shadow/.test(q))return [`You lower your presence instead of your head. The trick is not becoming invisible; it is giving observers a more convenient thing to notice.`,()=>{gainSkill("Stealth",10);gainAttr("Agility",5);S.player.heat=Math.max(0,S.player.heat-1)}];return [`You choose something the scene did not prepare for: “${t}” The immediate consequence is small—a changed expression, a shifted stance, someone deciding whether to remember your name. The delayed consequence has already begun.`,()=>{gainAttr("Will",5);if(npc)remember(npc,`Player unexpectedly chose to: ${t}`);scheduleFallout(2,{location:S.world.location,text:`A strange choice by ${S.player.name} at ${S.world.location} has developed consequences.`})}]}

function relationshipCallback(npc){if(!npc)return "";let n=MURIM_ENCOUNTERS.get(S,npc);if(!n)return '';let b=n.beliefs||{};let bits=[];if(n.trust>=4)bits.push("trust");if(n.respect>=4)bits.push("respect");if(n.fear>=3)bits.push("fear");if(b.honest<=-2)bits.push("doubt");if(!bits.length)return "";return `${n.name}'s reaction carries ${bits.join(", ")} from earlier encounters.`}
function originOpeningEffect(action,npc){
 const n=S.npcs[npc],o=openingRecord();if(!n)return null;
 const voice={han:"A question asked with restraint can survive its answer.",seo:"Show me what you noticed. Your name can wait.",mu:"Careful. An answer is a kind of invitation.",jin:"Keep the details. Someone has worked hard to remove them.",tang:"First we establish what happened. Then we decide what can be repaired.",gwak:"Every answer has an owner. Find out who paid for yours.",baek:"Say what you mean. I can respect that."}[npc]||"Tell me what you intend to do next.";
 const replies={
 hanRespect:["You ask about the history that brought you to "+S.world.location+". "+n.name+" lowers their voice. “"+voice+"” They agree to hear your account before deciding what your origin entitles anyone to demand.",()=>{n.trust+=2;n.respect+=2;believe(npc,"honest",1);gainSkill("Persuasion",8)}],
 vessel:["You connect the five cards to the unexplained detail before you: "+o.variant.aftershock+" "+n.name+" asks you to preserve that evidence. The word Vessel gives your question a direction; it does not make this witness know the answer.",()=>{S.world.threads["Vessel Mystery"]++;gainSkill("Investigation",10);remember(npc,"Asked about the Vessel at "+S.world.location+".")}],
 mu:["You test "+n.name+"'s composure instead of accepting the role prepared for you. They hold your gaze, reassessing the stranger in front of them. “"+voice+"” Your challenge earns attention as well as respect; secrecy will be harder now.",()=>{n.respect+=3;S.player.heat++;believe(npc,"ambitious",2)}],
 formation:["You study the cards and your surroundings before committing to an explanation. A scored channel repeats in the card's metallic pattern, interrupting an otherwise deliberate design. You record the irregularity. "+n.name+" watches you choose evidence over spectacle.",()=>{gainAttr("Insight",12);gainSkill("Formations",14+fateBonus("formation"));S.world.flags.tamperedFormation=true;S.world.threads["Black Lotus Trail"]++}]
 };return replies[action]||null;
}
function resolve(a,label,npc){if(S.flow.mode!=="scene"||S.flow.resolvedSceneId===S.scene?.id)return;if(a==="buyInfo"&&S.player.silver<10){setReaction("Gwak glances at your purse and snorts. “Information does not become free because you asked confidently.”",npc,label);return}
 S.actionNo++;let e=(S.scene?.questId&&a.startsWith("gq"))?resolveGeneratedQuest(a,S.scene.questId):(S.scene?.id==="opening"?originOpeningEffect(a,npc):null)||effects[a]||procEffect(a,label,npc)||customEffect(label,npc);if(!e||typeof e[1]!=="function"){setReaction("The moment passes, but the world fails to resolve the action cleanly. You regain your footing and can continue.",npc,label);return}e[1](S);remember(npc,`Day ${S.world.day}: ${label}`);record(label,e[0],npc);note(`${S.world.location}: ${label}`);syncQuests();let cb=relationshipCallback(npc);setReaction(e[0]+(cb?`\n\n${cb}`:""),npc,label);save()}
function setReaction(text,npc,label){S.reaction={sceneId:S.scene?.id||null,npc,label,text,impact:`HP ${S.player.hp}/${S.player.maxHp} • Qi ${S.player.qi}/${S.player.maxQi} • Reputation ${S.player.rep} • Heat ${S.player.heat}`};S.flow.mode="reaction";S.flow.resolvedSceneId=S.scene?.id||null;S.flow.prosePage=0;S.flow.choicePage=0;save();renderStory()}
function continueAfterReaction(talk=false){if(S.flow.mode!=="reaction"||!S.reaction||S.combat)return;let pending=S.world.flags.pendingCombat;delete S.world.flags.pendingCombat;tick();S.reaction=null;S.flow.mode="scene";S.flow.resolvedSceneId=null;let dest=S.world.flags.pendingTravel;delete S.world.flags.pendingTravel;if(pending){startCombat(pending.enemy,pending.difficulty,pending.npc);return}if(dest){S.scene=null;S.conversation=null;travelTo(dest);return}if(talk&&S.scene?.npc&&S.npcs[S.scene.npc]?.location===S.world.location){conversation(S.scene.npc,false);renderStory();return}setScene(nextScene());renderStory()}

const CONVERSATION_TOPICS=["convGoal","convOpinion","convFear","convVessel","convSecret","convPast","convWorld","convBond","convHelp","convChallenge"];
function ensureDialogueState(n){n.dialogue??={counts:{},lastDay:-99,lastAction:"",offerHistory:[],chosenHistory:[]};n.dialogue.counts??={};n.dialogue.offerHistory??=[];n.dialogue.chosenHistory??=[];return n.dialogue}
function dialogueWorldBeat(){let c=(S.world.simulation?.chronicle||[])[0];if(c?.text)return c.text;let f=Object.entries(S.world.factions||{}).sort((a,b)=>(b[1].awareness||0)-(a[1].awareness||0))[0];return f?`${f[0]} is currently ${String(f[1].operation||"making quiet moves").toLowerCase()}.`:`${S.world.location} is changing in small ways even while this conversation happens.`}
function conversationOption(npc,a){let n=S.npcs[npc],mem=salientMemory(n)||n.memory?.[0]||"your earlier encounters",loc=S.world.location,bond=n.bond||0,trust=n.trust||0;
 const options={
  convGoal:[`Ask what ${n.name} is trying to accomplish right now`,"Benefit: clearer motive, possible Trust, and a goal future callbacks can reference. Risk: repeatedly asking earns less. Consequence: their answer can reshape how you interpret later requests."],
  convOpinion:[`Ask how their opinion of you has changed`,"Benefit: relationship clarity and Persuasion growth. Risk: you may hear distrust, fear, or criticism you cannot take back. Consequence: the stated judgment becomes part of your shared history."],
  convFear:[`Ask what outcome they are genuinely afraid of`,"Benefit: fresh vulnerability can raise Trust and expose larger threats. Risk: personal pressure can close them off if overused. Consequence: fears may return as NPC-initiated warnings or requests."],
  convVessel:[`Press for what they know about the Vessel program`,`${trust>=4?"Benefit: your current trust may unlock real Vessel intelligence and Investigation progress.":"Benefit: even a refusal reveals the boundary of their trust."} Risk: advertises how deeply you are pursuing the mystery. Consequence: repeated interest can make this topic part of faction attention.`],
  convSecret:[`Point out the part of their story that still does not fit`,"Benefit: may reveal a secret, contradiction, or useful lie. Risk: pushing the same seam too often can harden caution. Consequence: discovered secrets permanently change later dialogue."],
  convPast:[`Return to the memory of ${String(mem).slice(0,86)}`,"Benefit: turns shared history into Bond, Trust, or reconciliation instead of disposable flavor. Risk: painful memories can reopen tension. Consequence: whichever meaning you give the memory can surface in future callbacks."],
  convWorld:[`Ask what has changed around ${loc} while you were occupied`,"Benefit: current world/faction intelligence and Investigation growth with little social risk. Risk: reveals what you are monitoring. Consequence: connects off-screen simulation to what this NPC believes is happening now."],
  convBond:[`Ask what they want your relationship to become`,`${bond>=5?"Benefit: your existing bond is strong enough for a candid answer and possible Affection/Romance growth.":"Benefit: establishes expectations before the relationship grows further."} Risk: asking too early can create distance. Consequence: future relationship scenes inherit the answer.`],
  convHelp:[`Offer concrete help toward their goal: ${String(n.goal||"the problem they are carrying").slice(0,90)}`,"Benefit: Trust, Bond, and a real debt can grow. Risk: the promise creates an obligation rather than free approval. Consequence: they may initiate a later scene to call in the offer."],
  convChallenge:[`Challenge the assumption behind their current plan`,"Benefit: can gain Respect, Will, and a more honest answer. Risk: fragile Trust may fall and a Grudge can begin. Consequence: future arguments remember whether you challenged them constructively or contemptuously."]
 };
 let q=options[a]||["Ask a different question","Benefit and risk depend on your existing history."];return [q[0],a,q[1]]}
function conversationChoices(npc){let n=S.npcs[npc],d=ensureDialogueState(n),prev=new Set(d.offerHistory[0]||[]),prev2=new Set(d.offerHistory[1]||[]),recentChosen=new Set((d.chosenHistory||[]).slice(0,3));let scored=CONVERSATION_TOPICS.map(a=>{let score=100-(d.counts[a]||0)*11;if(prev.has(a))score-=70;if(prev2.has(a))score-=18;if(recentChosen.has(a))score-=45;if(a==="convPast"&&n.memory?.length)score+=24;if(a==="convBond")score+=(n.bond||0)>=5?30:-10;if(a==="convSecret")score+=(n.trust||0)>=3?18:0;if(a==="convVessel")score+=(S.world.threads?.["Vessel Mystery"]||0)>=2?18:0;if(a==="convWorld")score+=(S.world.simulation?.chronicle||[]).length?20:5;if(a==="convHelp"&&n.goal)score+=16;if(a==="convChallenge")score+=(n.respect||0)>=3?14:0;if(a==="convFear")score+=(n.trust||0)>=2?12:0;score+=(hash(`${S.seed}|dialogue-offer|${npc}|${a}|${S.world.day}|${S.actionNo}|${S.conversation?.turn||0}`)%17)/10;return {a,score}}).sort((x,y)=>y.score-x.score);let selected=scored.slice(0,3).map(x=>x.a);d.offerHistory.unshift(selected);d.offerHistory=d.offerHistory.slice(0,6);return selected.map(a=>conversationOption(npc,a))}
function conversation(id,preserve=true){if(S.chat?.pendingId&&!v251Resolving){alert("Finish the pending response before beginning another conversation.");return}if(S.combat)return;if(!S.npcs[id]||S.npcs[id].location!==S.world.location){alert("Travel to this person’s location before talking.");return}if(S.flow.mode==="reaction"){alert("Continue the current outcome first.");return}if(preserve&&S.scene&&!S.scene.conversation)deferCurrentSceneForTravel();let n=S.npcs[id],d=ensureDialogueState(n),r=rng(hash(`${S.seed}|talk|${id}|${S.actionNo}|${n.memory.length}|${d.offerHistory.length}`)),callback=salientMemory(n)||n.memory?.[0]||"your first meeting",belief=n.beliefs||{},relationship=n.relationshipStatus||relationBand(n.bond||0),worldBeat=dialogueWorldBeat();S.conversation={npc:id,turn:(S.conversation?.npc===id?S.conversation.turn+1:1)};let openings=[`${n.name} lets the silence settle before speaking. ${NPC_VOICE[id]?`Their ${NPC_VOICE[id].cadence} cadence makes even a simple question feel deliberate.`:"They watch you closely enough that careless words would become evidence."}`,`${n.name} stays instead of finding an excuse to leave. In the Jianghu, that is its own kind of answer.`,`${n.name} studies you for a moment as though comparing the person in front of them with the version carried by rumor.`];let prompts=[`“Ask the question that would actually change what you do next,” ${n.name} says.`,`“Three honest questions are worth more than ten polite ones,” ${n.name} says. “Choose one.”`,`“If you want a real answer, ask something with a cost,” ${n.name} says.`];setScene({id:`talk-${id}-${S.actionNo}-${S.conversation.turn}`,conversation:true,npc:id,title:`Conversation — ${n.name}`,text:[pick(openings,r),`Your relationship is ${relationship}. Between you sits the memory of ${callback}. ${belief.honest<0?`${n.name} still carries doubt about your honesty.`:belief.honest>2?`${n.name} currently expects you to speak plainly.`:"Neither of you can rely on trust alone."}`,`Outside this conversation, the world has not paused: ${worldBeat} ${n.name}'s own priority remains ${String(n.goal||"unclear").replace(/\.$/,"")}.`,pick(prompts,r)],choices:conversationChoices(id)})}
function conversationEffect(a,npc){
 let n=S.npcs[npc],v=NPC_VOICE[npc],ctx=dialogueContext(npc,a),freshTopic=ctx.count===0||ctx.days>=5,mem=ctx.memory;
 if(a==="convGoal"){let line=ctx.pick([`${n.name} answers with the formal version first: “${n.goal}” Then their gaze shifts. “The harder part is deciding what I refuse to become while pursuing it.”`,`${n.name} turns the question around for a moment before answering. “${n.goal}.” They tap one finger against the table. “You have heard the goal before. What changed is the price I think it is worth.”`,`${n.name} gives you a tired half-smile. “Still ${String(n.goal).replace(/^./,m=>m.toLowerCase())}. But ${mem} changed which compromises I can pretend are harmless.”`]);return [line,()=>{if(freshTopic)n.trust+=ctx.count?1:2;remember(npc,`Spoke honestly about their current goal on Day ${S.world.day}.`)}]}
 if(a==="convOpinion"){let line=ctx.pick([`“You want the polite answer?” ${n.name} asks. “No. I trust you ${n.trust>=3?"more than I expected":"less than you probably hope"}, respect you ${n.respect>=3?"enough to disagree with you":"enough to keep watching"}, and fear you ${n.fear>=3?"more than I admit":"less than the rumors suggest"}.”`,`“My opinion of you is not one thing,” ${n.name} says. “It is ${n.trust>=4?"trust":"caution"}, ${n.respect>=4?"respect":"measurement"}, and the memory of ${mem}.”`,`“Today?” ${n.name} says. “You are the sum of what you did after people stopped looking. I am still deciding whether that makes you safer or more dangerous.”`]);return [line,()=>{if(freshTopic)n.respect++;gainSkill("Persuasion",freshTopic?5:2)}]}
 if(a==="convFear"){let line=ctx.pick([`The question lands harder than a threat. ${n.name}'s expression closes, then opens by a fraction. “That the people moving pieces around us already know which of us they are willing to lose.”`,`“I fear becoming predictable to someone patient,” ${n.name} says. “Patterns can be exploited. Even loyalty can become a map.” Their eyes flick briefly toward you. “Especially loyalty.”`,`${n.name} is quiet long enough to make the answer costly. “I fear that ${mem} was not an isolated moment—that it was evidence of a larger design we still cannot see.”`]);return [line,()=>{if(freshTopic)n.trust+=ctx.count?1:3;if(ctx.count===0)S.world.threads["Vessel Mystery"]++;remember(npc,`Shared a fear with ${S.player.name} on Day ${S.world.day}.`)}]}
 if(a==="convSecret"){let answer=secretResponse(npc),tail=ctx.count?ctx.pick([` ${n.name} watches to see whether you will push the same seam twice.`,` The old answer has not disappeared; its consequences have simply become easier to see.`,` They remember that you asked before, which changes the risk of asking again.`]):"";return [(answer||`${n.name} gives you nothing you can use.`)+tail,()=>{gainSkill("Investigation",ctx.count?2:4);if(S.world.secrets[npc]?.revealed&&freshTopic)n.trust+=1}]}
 if(a==="convVessel"){let deep=n.trust>=4||n.known?.length,line=deep?ctx.pick([`${n.name} glances toward the nearest exit. “The word ‘Vessel’ was not invented for you. You are a continuation. The dangerous question is whether someone expected you specifically.”`,`${n.name} lowers their voice. “Every time we say ‘Vessel’ as though it were a title, we make the old mistake. It was a program, a category, and perhaps a succession.”`,`“The mystery has changed,” ${n.name} says. “At first we asked what you are. Now I am asking who benefits if you believe there was only one Vessel left.”`]):ctx.pick([`${n.name} studies you. “You have not yet given me a reason to put that knowledge in your hands.”`,`“You are asking for a dangerous truth before we have established what you do with ordinary ones,” ${n.name} says.`,`“Not yet,” ${n.name} says. “Bring me a reason stronger than curiosity.”`]);return [line,()=>{if(deep){if(ctx.count===0)S.world.threads["Vessel Mystery"]++;gainSkill("Investigation",ctx.count?3:7)}else if(freshTopic)n.respect+=1}]}
 if(a==="convPast"){let rough=(n.grudge||0)>=3,line=rough?`${n.name} does not soften the memory for your comfort. “${mem}.” They repeat it without decoration. “If we are going to keep knowing each other, we decide what that meant—not pretend it did not happen.”\n\nThe conversation does not erase the old wound, but it gives both of you a new memory beside it.`:`${n.name}'s expression changes when you return to the shared memory: ${mem}. “I wondered whether you remembered it the same way.”\n\nFor a while you compare details rather than conclusions. What mattered becomes clearer precisely because neither of you remembered it perfectly.`;return [line,()=>{if(rough){n.grudge=Math.max(0,(n.grudge||0)-1);n.trust+=1;n.bond+=1}else{n.bond+=2;n.trust+=1;n.sharedHistory=(n.sharedHistory||0)+1}gainAttr("Insight",4);remember(npc,`Revisited a shared memory with ${S.player.name} and gave it new meaning on Day ${S.world.day}.`,3);refreshRelation(npc)}]}
 if(a==="convWorld"){let beat=dialogueWorldBeat(),line=`${n.name} does not answer with a rumor list. They separate what they saw, what they inferred, and what someone paid to make people believe.\n\n“${beat}” Their finger traces a small circle on the table. “That is the visible part. The useful question is who benefits if everyone treats it as ordinary.”`;return [line,()=>{gainSkill("Investigation",6);gainAttr("Perception",3);remember(npc,`Compared notes with ${S.player.name} about how the living world was changing on Day ${S.world.day}.`)}]}
 if(a==="convBond"){let close=(n.bond||0)>=5,line=close?`${n.name} does not answer immediately. The question is more dangerous than asking about enemies because neither of you can blame a faction for the answer.\n\n“I want this to become something we choose on purpose,” ${n.name} says. “Not just a chain of emergencies that keeps putting us in the same room.”`:`${n.name} blinks once. “We barely know what we are to each other yet.” The answer is not rejection so much as a boundary honestly named.\n\n“Ask me again after we have more than danger in common.”`;return [line,()=>{if(close){n.bond+=2;n.affection=(n.affection||0)+1;n.trust+=1;if((n.romance||0)>0||(n.affection||0)>=6)n.romance=(n.romance||0)+1}else{n.respect+=1;n.bond+=1}refreshRelation(npc);remember(npc,`Spoke directly with ${S.player.name} about what their relationship should become.`,4)}]}
 if(a==="convHelp"){let line=`You do not offer vague loyalty. You ask what would materially move ${n.name}'s goal forward and what it would cost you to help. That changes the expression on their face.\n\n“Careful,” ${n.name} says. “If I tell you, I may actually expect you to come.” They name a concrete need, and you agree to be reachable. The promise now exists outside the conversation.`;return [line,()=>{n.trust+=2;n.bond+=2;n.debt=(n.debt||0)+1;S.world.narrative.consequenceLedger.unshift({day:S.world.day,type:"npc-promise",npc,why:`${S.player.name} offered concrete help toward ${n.name}'s goal.`});S.world.narrative.consequenceLedger=S.world.narrative.consequenceLedger.slice(0,80);schedule("npcPromise",2+hash(`${npc}|${S.world.day}`)%3,{npc,goal:n.goal});remember(npc,`${S.player.name} made a concrete offer of help on Day ${S.world.day}.`,5);refreshRelation(npc)}]}
 if(a==="convChallenge"){let stable=(n.trust||0)+(n.respect||0)>=5,line=stable?`You challenge the assumption instead of the person. ${n.name} starts to answer defensively, stops, and reconstructs the argument from the beginning.\n\n“That is irritating,” they say at last. “Which is not the same as wrong.” What follows is sharper and more useful than the plan they entered the conversation with.`:`You press against the weakest assumption in ${n.name}'s plan. Their posture hardens before their words do.\n\n“You have not earned the right to call that foolish,” they say. The objection lands anyway—but so does the fact that you chose confrontation before trust.`;return [line,()=>{gainAttr("Will",5);if(stable){n.respect+=2;n.trust+=1;gainSkill("Persuasion",5)}else{n.respect+=1;n.trust-=1;n.grudge=(n.grudge||0)+1}remember(npc,`${S.player.name} challenged an assumption behind my plan instead of simply agreeing.`,3);refreshRelation(npc)}]}
 if(a==="convEnd"){let line=ctx.pick([`You end the conversation before it becomes interrogation. ${n.name} notices. “Next time,” they say, “I may be the one with questions.”`,`${n.name} does not try to keep you. “Go,” they say. “A conversation that survives an ending is worth having again.”`,`You rise first. ${n.name} studies you for a moment, then nods. “Enough for today. What matters is whether any of this changes what we do next.”`]);return [line,()=>{if(freshTopic&&ctx.count===0)n.trust++}]}
 return [`${n.name} says nothing. The silence itself is an answer.`,()=>{}]
}
function dialogueSnapshot(npc){let n=S.npcs[npc];return {trust:n.trust||0,respect:n.respect||0,fear:n.fear||0,bond:n.bond||0,affection:n.affection||0,romance:n.romance||0,debt:n.debt||0,grudge:n.grudge||0,vessel:S.world.threads?.["Vessel Mystery"]||0,rep:S.player.rep||0,heat:S.player.heat||0}}
function dialogueDelta(before,npc){let after=dialogueSnapshot(npc),names={trust:"Trust",respect:"Respect",fear:"Fear",bond:"Bond",affection:"Affection",romance:"Romance",debt:"Debt",grudge:"Grudge",vessel:"Vessel thread",rep:"Reputation",heat:"Heat"},parts=[];for(const k of Object.keys(names)){let d=after[k]-before[k];if(d)parts.push(`${names[k]} ${d>0?"+":""}${d}`)}return parts.length?parts.join(" • "):"No immediate numerical shift — the information and memory are the consequence."}
function dialogueFuture(a,npc){let n=S.npcs[npc],map={convGoal:`${n.name}'s stated goal can now color future requests and judgments.`,convOpinion:`This opinion is now part of the relationship history future reactions can contradict or confirm.`,convFear:`The fear you uncovered can become motive for an NPC-initiated warning or decision.`,convVessel:`Your interest in the Vessel mystery remains visible to ${n.name}.`,convSecret:`Any secret revealed here permanently changes what later scenes may assume you know.`,convPast:`The meaning you gave a shared memory can return in later relationship callbacks.`,convWorld:`This intelligence links off-screen world simulation to your next decisions.`,convBond:`The relationship now carries a more explicit expectation about closeness.`,convHelp:`A real promise has been scheduled; ${n.name} may call in your offer later.`,convChallenge:`${n.name} will remember whether the challenge felt like respect or contempt.`};return map[a]||`${n.name} will remember the tone and substance of this exchange.`}
function resolveConversation(a,label,npc){if(S.flow.mode!=="scene")return;let before=dialogueSnapshot(npc),d=ensureDialogueState(S.npcs[npc]);S.actionNo++;let e=conversationEffect(a,npc);e[1](S);if(a!=="convEnd"){d.chosenHistory.unshift(a);d.chosenHistory=d.chosenHistory.slice(0,8)}remember(npc,`Day ${S.world.day}: ${label}`);record(label,e[0],npc);let delta=dialogueDelta(before,npc),future=dialogueFuture(a,npc),body=a==="convEnd"?e[0]:`${e[0]}\n\nImmediate consequence: ${delta}\n\nLonger-term consequence: ${future}`;S.reaction={sceneId:S.scene.id,npc,label,text:body,impact:delta};S.flow.mode="reaction";S.flow.resolvedSceneId=S.scene.id;S.world.flags.afterConversation=a==="convEnd"?"exit":"continue";save();renderStory()}

