  if(t==="Minor Meridian Sweep"){let gain=6+Math.floor(S.player.skills["Qi Control"].v/2);S.player.qi=Math.min(S.player.maxQi,S.player.qi+gain);c.momentum=clamp(momentum+1+mods.momentum,0,3);c.log.push(`Minor Meridian Sweep clears the impact from your channels. You recover ${gain} Qi and preserve ${c.momentum}/3 momentum.`);gainSkill("Qi Control",4);gainArt("Basic Meridian Breathing",4,t)}
