function show(view){v250View=view;if(!S.created)return;window.scrollTo?.(0,0);if(S.combat){renderCombat();return}$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==="story"){$("#altView").classList.add("hidden");$("#storyView").classList.remove("hidden");$("#customForm").classList.remove("hidden");renderStory()}else alt(view)}

function resetJourney(){
 if(!confirm("Erase this Living Murim save and begin again?"))return;
 suppressAutoSave=true;
 try{
  for(let i=localStorage.length-1;i>=0;i--){
   let k=localStorage.key(i);
   if(k===KEY||k===V236_BACKUP_KEY)localStorage.removeItem(k);
  }
 }catch(e){}
 S=fresh();
 hydrateImported();
 $("#modal").classList.add("hidden");
 $("#modalBody").innerHTML="";
 $("#customAction").value="";
 $("#name").value="";
 creation();
 $("#creation").classList.remove("hidden");
 $("#game").classList.add("hidden");
 $$("#nav button").forEach(b=>b.classList.toggle("active",b.dataset.view==="story"));
 checkBegin();
 suppressAutoSave=false;
 save();
 $("#status").textContent="Journey reset • choose your new fate";
}

function choiceSignal(action,npc){let n=npc&&S.npcs[npc],name=n?.name||"the Jianghu";if(action==="procTalk")return `${name} will remember whether you asked or demanded.`;if(action==="procReconstruct")return "Evidence synthesis • connects clues across scenes and advances investigative understanding.";if(action==="procReadPerson")return `${name} is the evidence • uses social specialization and relationship history.`;if(action==="procQiRead")return "Qi perception • spends 3 Qi to reveal residual qi evidence.";if(action==="procObserve")return "Low exposure • reveals evidence and changes what becomes possible next.";if(action==="procAct")return "High exposure • heat, reputation, and faction attention may move.";if(action==="procFollow")return "Information gained • safety and time are the price.";if(action==="procLeave")return "Unresolved • this can return later through fallout or a callback.";if(action.startsWith("gq"))return action==="gqAbandon"?"Ends the thread • the faction will resolve the vacuum without you.":"Advances the thread • your method changes faction standing.";if(action==="convGoal")return `Benefit: motive + possible Trust • Risk: repetition loses value • Later: ${name} can call back to this goal.`;if(action==="convOpinion")return `Benefit: relationship clarity + Persuasion • Risk: honest criticism becomes history.`;if(action==="convFear")return `Benefit: vulnerability + possible Trust • Risk: pressure if repeated • Later: fear can drive callbacks.`;if(action==="convVessel")return `Benefit: Vessel intelligence when trust allows • Risk: exposes your interest to ${name}.`;if(action==="convSecret")return `Benefit: secrets + Investigation • Risk: repeated probing hardens caution.`;if(action==="convPast")return `Benefit: Bond/Insight or reconciliation • Risk: old tension may reopen.`;if(action==="convWorld")return `Benefit: current world intelligence + Investigation • Risk: reveals what you are monitoring.`;if(action==="convBond")return `Benefit: Bond/Affection clarity • Risk: asking too early can create distance.`;if(action==="convHelp")return `Benefit: Trust/Bond/Debt • Risk: creates a real obligation and future callback.`;if(action==="convChallenge")return `Benefit: Respect/Will and sharper truth • Risk: Trust loss or Grudge if the bond is fragile.`;if(action==="relAnswer")return `Benefit: Bond +3, Trust +2, Affection +1 • Low risk • Later: sincerity becomes shared history.`;if(action==="relMeal")return `Benefit: Bond +4, Affection +2, Cooking growth • Cost: time • Later: creates a private shared memory.`;if(action==="relDeep")return `Benefit: Bond +3, Trust +3, Persuasion growth • Risk: vulnerability can change expectations.`;if(action==="relHear")return `Benefit: lowers Grudge/Jealousy and raises Respect • Cost: you listen before defending yourself.`;if(action==="relRepair")return `Benefit: major Grudge/Jealousy repair + Trust/Bond • Cost: up to 15 silver and pride.`;if(action==="relStand")return `Benefit: Respect + Will • Risk: Bond falls and Grudge/Jealousy rise.`;if(action.startsWith("rel")||action.startsWith("conv"))return `${name} will store the tone of this answer in their memory.`;if(action==="formation")return "Evidence-first • slower now, but hidden structure may become visible.";if(action==="mu")return "Provocation • invites a sharper response and more attention.";if(action==="vessel")return "Truth-seeking • advances the mystery while exposing your interest.";if(action==="hanRespect")return "Restraint • builds a relationship without surrendering initiative.";return n?`${name} will remember how you handled this.`:"The Jianghu will carry the direction of this choice forward."}
